mapper.select:
SELECT DISTINCT
    count( b.PERSONNEL_NAME ) MASCULINE_NUMBER
FROM
    `my_community_area` a
    LEFT JOIN `my_personnel` b ON a.AREA_CODE = b.AREA_CODE
WHERE
    a.COMMUNITY_CODE = #{sessionCommunityCode}
    AND b.COMMUNITY_CODE = #{sessionCommunityCode}
    AND b.AREA_CODE = #{areaCode}
    AND b.NAT_RESULT = 120032
